#!/usr/bin/env python3\n\"\"\"\nAURA IA - Interface Interativa Principal\nAssistente Inteligente Completo\n\"\"\"\n\nimport os\nimport sys\nfrom datetime import datetime\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\ntry:\n    from aura.core import AURA\nexcept ImportError:\n    print(\"❌ Erro: Módulo 'aura' não encontrado. Execute: pip install -r requirements.txt\")\n    sys.exit(1)\n\n\nclass AURAInterface:\n    \"\"\"Interface interativa para AURA\"\"\"\n\n    def __init__(self):\n        \"\"\"Inicializa a interface\"\"\"\n        self.aura = None\n        self.historico = []\n        self.inicializar()\n\n    def inicializar(self):\n        \"\"\"Inicializa AURA\"\"\"\n        print(\"\\n\" + \"=\"*60)\n        print(\"🌟 AURA - Assistente Inteligente Completo\".center(60))\n        print(\"=\"*60)\n        print(\"\\n⏳ Inicializando AURA...\\n\")\n\n        try:\n            api_key = os.getenv(\"OPENAI_API_KEY\") or os.getenv(\"ANTHROPIC_API_KEY\")\n            \n            if not api_key:\n                print(\"⚠️  Aviso: Nenhuma chave de API encontrada em .env\")\n                print(\"📝 Configure as variáveis de ambiente para usar AURA\\n\")\n                self.aura = AURA(demo_mode=True)\n                print(\"✅ AURA iniciado em modo demonstração\\n\")\n            else:\n                self.aura = AURA()\n                print(\"✅ AURA inicializado com sucesso!\\n\")\n        except Exception as e:\n            print(f\"❌ Erro ao inicializar AURA: {e}\")\n            sys.exit(1)\n\n    def exibir_menu(self):\n        \"\"\"Exibe menu de opções\"\"\"\n        print(\"\\n\" + \"-\"*60)\n        print(\"📋 MENU DE OPÇÕES\")\n        print(\"-\"*60)\n        print(\"1️⃣  Chat com AURA\")\n        print(\"2️⃣  Analisar Sentimento\")\n        print(\"3️⃣  Gerar Conteúdo\")\n        print(\"4️⃣  Traduzir Texto\")\n        print(\"0️⃣  Sair\")\n        print(\"-\"*60)\n\n    def chat(self):\n        \"\"\"Chat com AURA\"\"\"\n        print(\"\\n💬 MODO CHAT (Digite 'sair' para voltar)\")\n        print(\"-\"*60)\n        \n        while True:\n            try:\n                mensagem = input(\"Você: \").strip()\n                \n                if mensagem.lower() == \"sair\":\n                    break\n                \n                if not mensagem:\n                    print(\"⚠️  Digite algo para continuar\\n\")\n                    continue\n                \n                print(\"\\n⏳ AURA está processando...\\n\")\n                resposta = self.aura.chat(mensagem)\n                print(f\"🤖 AURA: {resposta}\\n\")\n                \n            except KeyboardInterrupt:\n                print(\"\\n\\n⚠️  Chat interrompido\")\n                break\n            except Exception as e:\n                print(f\"❌ Erro: {e}\\n\")\n\n    def analisar_sentimento(self):\n        \"\"\"Analisa sentimento de um texto\"\"\"\n        print(\"\\n😊 ANÁLISE DE SENTIMENTO\")\n        print(\"-\"*60)\n        \n        texto = input(\"Digite o texto: \").strip()\n        \n        if not texto:\n            print(\"⚠️  Texto vazio\\n\")\n            return\n        \n        print(\"\\n⏳ Analisando...\\n\")\n        resultado = self.aura.analisar_sentimento(texto)\n        \n        print(\"📊 Resultado:\")\n        print(f\"   Sentimento: {resultado.get('sentimento').upper()}\")\n        print(f\"   Confiança: {resultado.get('confiança')*100:.1f}%\\n\")\n\n    def executar(self):\n        \"\"\"Loop principal\"\"\"\n        while True:\n            self.exibir_menu()\n            opcao = input(\"Escolha: \").strip()\n            \n            if opcao == \"1\":\n                self.chat()\n            elif opcao == \"2\":\n                self.analisar_sentimento()\n            elif opcao == \"0\":\n                print(\"\\n👋 Até logo!\\n\")\n                break\n            else:\n                print(\"❌ Opção inválida\\n\")\n\n\nif __name__ == \"__main__\":\n    try:\n        interface = AURAInterface()\n        interface.executar()\n    except KeyboardInterrupt:\n        print(\"\\n\\n👋 AURA foi interrompido.\\n\")\n        sys.exit(0)